<!-- generated by studio，请勿手工修改。 -->
<template>
  <ContentWrap>
    <el-form ref="queryFormRef" :inline="true" :model="queryParams" class="-mb-15px">
        <el-form-item label="试样名称" prop="sampleName">
          <el-input v-model="queryParams.sampleName" clearable placeholder="请输入试样名称" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="强度等级规格牌号" prop="strengthGrade">
          <el-input v-model="queryParams.strengthGrade" clearable placeholder="请输入强度等级规格牌号" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="工程部位" prop="engineeringLocation">
          <el-input v-model="queryParams.engineeringLocation" clearable placeholder="请输入工程部位" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="炉批号出厂编号" prop="furnaceBatchNumber">
          <el-input v-model="queryParams.furnaceBatchNumber" clearable placeholder="请输入炉批号出厂编号" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="生产厂家" prop="manufacturer">
          <el-input v-model="queryParams.manufacturer" clearable placeholder="请输入生产厂家" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="代表批量" prop="representativeBatch">
          <el-input v-model="queryParams.representativeBatch" clearable placeholder="请输入代表批量" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="委托编号" prop="entrustmentNumber">
          <el-input v-model="queryParams.entrustmentNumber" clearable placeholder="请输入委托编号" @keyup.enter="handleQuery" />
        </el-form-item>
      <el-form-item>
        <el-button @click="handleQuery"><Icon class="mr-5px" icon="ep:search" />查询</el-button>
        <el-button @click="resetQuery"><Icon class="mr-5px" icon="ep:refresh" />重置</el-button>
          <el-button type="primary" @click="openForm('create')">
            <Icon class="mr-5px" icon="ep:plus" />新增
          </el-button>
          <el-button :loading="exportLoading" type="success" @click="handleExport">
            <Icon class="mr-5px" icon="ep:download" />导出
          </el-button>
          <el-button :disabled="checkedIds.length === 0" type="danger" @click="handleDeleteBatch">
            <Icon class="mr-5px" icon="ep:delete" />批量删除
          </el-button>
      </el-form-item>
    </el-form>
  </ContentWrap>

  <ContentWrap>
    <el-table v-loading="loading" :data="rows" @selection-change="handleSelectionChange">
        <el-table-column align="center" type="selection" width="55" />
      <el-table-column align="center" label="行号" width="90">
        <template #default="scope">{{ (queryParams.pageNo - 1) * queryParams.pageSize + scope.$index + 1 }}</template>
      </el-table-column>
        <el-table-column label="试样名称" prop="sampleName" min-width="120" show-overflow-tooltip />
        <el-table-column label="强度等级规格牌号" prop="strengthGrade" min-width="120" show-overflow-tooltip />
        <el-table-column label="工程部位" prop="engineeringLocation" min-width="120" show-overflow-tooltip />
        <el-table-column align="center" :formatter="dateFormatter" label="成型日期" prop="formingDate" width="180" />
        <el-table-column label="炉批号出厂编号" prop="furnaceBatchNumber" min-width="120" show-overflow-tooltip />
        <el-table-column label="生产厂家" prop="manufacturer" min-width="120" show-overflow-tooltip />
        <el-table-column label="样品数量" prop="sampleQuantity" min-width="120" show-overflow-tooltip />
        <el-table-column label="代表批量" prop="representativeBatch" min-width="120" show-overflow-tooltip />
        <el-table-column label="样品状态" prop="sampleStatus" min-width="120" show-overflow-tooltip />
        <el-table-column label="委托编号" prop="entrustmentNumber" min-width="120" show-overflow-tooltip />
        <el-table-column align="center" fixed="right" label="操作" width="160">
          <template #default="scope">
            <el-button link type="primary" @click="openDetail(scope.row.id)">查看</el-button>
            <el-button link type="primary" @click="openForm('update', scope.row.id)">编辑</el-button>
            <el-button link type="danger" @click="handleDelete(scope.row.id)">删除</el-button>
          </template>
        </el-table-column>
    </el-table>
    <Pagination v-model:limit="queryParams.pageSize" v-model:page="queryParams.pageNo" :total="total" @pagination="getList" />
  </ContentWrap>

  <BoxunCommissionOrderSampleForm ref="formRef" @success="getList" />
  <BoxunCommissionOrderSampleDetail ref="detailRef" />
</template>

<script setup lang="ts">
import { dateFormatter } from '@/utils/formatTime'
import request from '@/config/axios'
import download from '@/utils/download'
import * as BoxunCommissionOrderSampleApi from './BoxunCommissionOrderSampleApi'
import BoxunCommissionOrderSampleForm from './BoxunCommissionOrderSampleForm.vue'
import BoxunCommissionOrderSampleDetail from './BoxunCommissionOrderSampleDetail.vue'

type BoxunCommissionOrderSampleRow = Awaited<ReturnType<typeof BoxunCommissionOrderSampleApi.getBoxunCommissionOrderSamplePage>>['list'][number]
type EntityId = string | number

defineOptions({ name: 'BoxunCommissionOrderSample' })

const message = useMessage()
const { t } = useI18n()
const loading = ref(false)
const total = ref(0)
const rows = ref<BoxunCommissionOrderSampleRow[]>([])
const queryFormRef = ref()
const queryParams = reactive({
  pageNo: 1,
  pageSize: 10,
  sampleName: '',
  strengthGrade: '',
  engineeringLocation: '',
  furnaceBatchNumber: '',
  manufacturer: '',
  representativeBatch: '',
  entrustmentNumber: ''
})



const getList = async () => {
  loading.value = true
  try {
    const data = await BoxunCommissionOrderSampleApi.getBoxunCommissionOrderSamplePage(queryParams)
    rows.value = data.list
    total.value = Number(data.total)
  } finally {
    loading.value = false
  }
}

const handleQuery = () => {
  queryParams.pageNo = 1
  getList()
}

const resetQuery = () => {

  queryFormRef.value?.resetFields()

  handleQuery()
}

const formRef = ref()
const openForm = (type: 'create' | 'update', id?: EntityId) => {
  formRef.value?.open(type, id, type === 'create' ? undefined : undefined)
}


const detailRef = ref()
const openDetail = (id: EntityId) => {
  detailRef.value?.open(id)
}



const handleDelete = async (id?: EntityId) => {
  if (id === undefined) return
  await message.delConfirm()
  await BoxunCommissionOrderSampleApi.deleteBoxunCommissionOrderSample(id)
  message.success(t('common.delSuccess'))
  await getList()
}

const checkedIds = ref<EntityId[]>([])
const handleSelectionChange = (rows: BoxunCommissionOrderSampleRow[]) => {
  checkedIds.value = rows.map((row) => row.id).filter((id): id is EntityId => id !== undefined)
}

const handleDeleteBatch = async () => {
  await message.delConfirm()
  await BoxunCommissionOrderSampleApi.deleteBoxunCommissionOrderSampleList(checkedIds.value)
  message.success(t('common.delSuccess'))
  checkedIds.value = []
  await getList()
}
const exportLoading = ref(false)
const handleExport = async () => {
  await message.exportConfirm()
  exportLoading.value = true
  try {
    const data = await request.download({ url: '/boxun/commission-order-sample/export-excel', params: queryParams })
    download.excel(data, 'boxunCommissionOrderSample.xls')
  } finally {
    exportLoading.value = false
  }
}

onMounted(getList)
</script>
